	public void Initialize()
	{
		for (int i = 0; i < fileWriteCallTimes.Length; i++)
		{
			fileWriteCallTimes[i] = DateTime.MinValue;
		}
		KFMonoBehaviourCallbackHooks.Instance.OnLateUpdateDelegate += PerformSave;
	}

	private void PerformSave()
	{
		if (saveGameRequested || saveConfigRequested)
		{
			if (saveGameRequested)
			{
				StoredCachedFileInternal();
				saveGameRequested = false;
			}
			if (saveConfigRequested)
			{
				saveConfigRequested = false;
			}
		}
	}

	private bool TryStartFileWriteOperations(int operationCount)
	{
		DateTime utcNow = DateTime.UtcNow;
		if (!fileWriteCallTimesInitialized)
		{
			fileWriteCallTimesInitialized = true;
			for (int i = 0; i < operationCount; i++)
			{
				fileWriteCallTimes[fileWriteCallTimesIndex] = utcNow;
				fileWriteCallTimesIndex = (fileWriteCallTimesIndex + 1) % fileWriteCallTimes.Length;
			}
			return true;
		}
		int num = 0;
		int num2 = fileWriteCallTimesIndex - 1;
		if (num2 < 0)
		{
			num2 += fileWriteCallTimes.Length;
		}
		int num3 = num2;
		while ((utcNow - fileWriteCallTimes[num3]).TotalSeconds <= 60.0)
		{
			num++;
			num3--;
			if (num3 < 0)
			{
				num3 += fileWriteCallTimes.Length;
			}
			if (num3 == num2)
			{
				break;
			}
		}
		if (num < 10)
		{
			fileWriteCallTimesInitialized = true;
			for (int j = 0; j < operationCount; j++)
			{
				fileWriteCallTimes[fileWriteCallTimesIndex] = utcNow;
				fileWriteCallTimesIndex = (fileWriteCallTimesIndex + 1) % fileWriteCallTimes.Length;
			}
			return true;
		}
		return false;
	}

	private void UpdateLastFileWriteTimes(int numberOfTimes)
	{
		int num = fileWriteCallTimesIndex - 1;
		if (num < 0)
		{
			num += fileWriteCallTimes.Length;
		}
		while (numberOfTimes > 0)
		{
			fileWriteCallTimes[num] = DateTime.UtcNow;
			num--;
			if (num < 0)
			{
				num += fileWriteCallTimes.Length;
			}
			numberOfTimes--;
		}
	}

