	public Dice TryToCreateForgedDice(DiceSave diceSave, Dice diceToAddToPool, out bool isForged)
	{
		isForged = false;
		if (diceSave.DiceFaceForged.Count > 0)
		{
			isForged = true;
			Dice dice = diceToAddToPool.InstantiateScriptableObjectTryingToCopyDiceFacesModded();
			for (int i = 0; i < diceSave.DiceFaceForged.Count; i++)
			{
				DiceFaceSave diceFaceSave = diceSave.DiceFaceForged[i];
				DiceFace diceFace = dice.GetDiceFaces()[diceFaceSave.FaceIndex];
				BattleAction battleAction = battleActionsList.GetBattleAction(diceFaceSave.BattleActionName);
				if (diceFaceSave.EnableSecondAction)
				{
					BattleAction battleAction2 = battleActionsList.GetBattleAction(diceFaceSave.SecondBattleActionName);
					diceFace = new DiceFace(diceFaceSave.FaceName, diceFaceSave.ActionValue, battleAction, diceFaceSave.SecondActionValue, battleAction2);
					diceFace.NewSecondBattleAction = battleAction2;
					diceFace.NewSecondActionValue = diceFaceSave.SecondActionValue;
				}
				else
				{
					diceFace = new DiceFace(diceFaceSave.FaceName, diceFaceSave.ActionValue, battleAction);
				}
				diceFace.NewActionValue = diceFaceSave.ActionValue;
				diceFace.NewBattleAction = battleAction;
				diceFace.KeepChanges = true;
				dice.GetDiceFaces()[diceFaceSave.FaceIndex] = diceFace;
			}
			diceToAddToPool = dice;
		}
		return diceToAddToPool;
	}

