	}

	public void ShareAnomalyAndAstreaLevelBetweenAllCharacters()
	{
		Character[] array = playerProgressionData.CharactersList.charactersList;
		int num = -1;
		int num2 = -1;
		for (int i = 0; i < array.Length; i++)
		{
			if (!array[i].CharacterEnum)
			{
				CharacterProgression characterProgression = array[i].CharacterProgression;
				if (characterProgression.UnlockedAnomalyLevel > num)
				{
					num = characterProgression.UnlockedAnomalyLevel;
				}
				if (characterProgression.UnlockedAstreaLevel > num2)
				{
					num2 = characterProgression.UnlockedAstreaLevel;
				}
			}
		}
		for (int j = 0; j < array.Length; j++)
		{
			if (!array[j].CharacterEnum)
			{
				CharacterProgression characterProgression2 = array[j].CharacterProgression;
				if (characterProgression2.UnlockedAnomalyLevel != -1)
				{
					characterProgression2.UnlockedAnomalyLevel = num;
					SaveCharacterUnlockedAnomalyLevel(array[j]);
				}
				if (characterProgression2.UnlockedAstreaLevel != -1)
				{
					characterProgression2.UnlockedAstreaLevel = num2;
					SaveCharacterUnlockedAstreaLevel(array[j]);
				}
			}
		}
	}

	private void LoadCharacterProgression(Character character)
	{
		CharacterProgression characterProgression = character.CharacterProgression;
		LoadCharacterUnlocked(character);
		LoadCharacterXP(character);
		characterProgression.AstreaHeartReached = LoadKey(GetCharacterSaveString(character, "AstreaHeartReachedSave"), defaultValue: false);
		characterProgression.CurrentAnomalyLevel = LoadKey(GetCharacterSaveString(character, "CurrentAnomalyLevelSave"), -1);
		characterProgression.UnlockedAnomalyLevel = LoadKey(GetCharacterSaveString(character, "UnlockedAnomalyLevelSave"), -1);
		characterProgression.CurrentAstreaLevel = LoadKey(GetCharacterSaveString(character, "CurrentAstreaLevelSave"), -1);
		characterProgression.UnlockedAstreaLevel = LoadKey(GetCharacterSaveString(character, "UnlockedAstreaLevelSave"), -1);
		characterProgression.AnomalyLevelsDefeated = LoadKey(GetCharacterSaveString(character, "AnomalyLevelsDefeated"), new List<int>());
		characterProgression.AstreaLevelsDefeated = LoadKey(GetCharacterSaveString(character, "AstreaLevelsDefeated"), new List<int>());
		if (characterProgression.AnomalyLevelsDefeated.Contains(0) && !characterProgression.AstreaLevelsDefeated.Contains(0))
		{
			characterProgression.AstreaLevelsDefeated.Add(0);
			SaveKey(GetCharacterSaveString(character, "AstreaLevelsDefeated"), characterProgression.AstreaLevelsDefeated);
			saveGameRequested = true;
		}
		characterProgression.MaxNonHiddenAnomalyLevelDefeated = LoadKey(GetCharacterSaveString(character, "MaxNonHiddenAnomalyLevelDefeated"), defaultValue: false);
		characterProgression.MaxNonHiddenAstreaLevelDefeated = LoadKey(GetCharacterSaveString(character, "MaxNonHiddenAstreaLevelDefeated"), defaultValue: false);
		characterProgression.MaxNonHiddenAnomalyAndAstreaDefeatedAtTheSameTime = LoadKey(GetCharacterSaveString(character, "MaxNonHiddenAnomalyAndAstreaDefeatedAtTheSameTime"), defaultValue: false);
		characterProgression.AnomalyLevelHiddenDefeated = LoadKey(GetCharacterSaveString(character, "AnomalyLevelHiddenDefeated"), defaultValue: false);
		characterProgression.AstreaLevelHiddenDefeated = LoadKey(GetCharacterSaveString(character, "AstreaLevelHiddenDefeated"), defaultValue: false);
		characterProgression.FirstChestPicksCounter = LoadKey(GetCharacterSaveString(character, "firstChestPicksCounterSave"), 0);
	}

