	public void SaveCurrentCharacterAnomalyAndAstreaLevelDefeated(bool onlyAnomaly)
	{
		if (ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentRunAnomalyLevel > -1 && !ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentCharacterProgression.AnomalyLevelsDefeated.Contains(ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentRunAnomalyLevel))
		{
			ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentCharacterProgression.AnomalyLevelsDefeated.Add(ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentRunAnomalyLevel);
			SaveKey(GetCharacterSaveString(ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentCharacter, "AnomalyLevelsDefeated"), ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentCharacterProgression.AnomalyLevelsDefeated);
		}
		if (ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentCharacterProgression.AnomalyLevelsDefeated.Contains(0) && !ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentCharacterProgression.AstreaLevelsDefeated.Contains(0))
		{
			ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentCharacterProgression.AstreaLevelsDefeated.Add(0);
			SaveKey(GetCharacterSaveString(ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentCharacter, "AstreaLevelsDefeated"), ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentCharacterProgression.AstreaLevelsDefeated);
		}
		if (!onlyAnomaly && ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentRunAstreaLevel > -1 && !ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentCharacterProgression.AstreaLevelsDefeated.Contains(ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentRunAstreaLevel))
		{
			ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentCharacterProgression.AstreaLevelsDefeated.Add(ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentRunAstreaLevel);
			SaveKey(GetCharacterSaveString(ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentCharacter, "AstreaLevelsDefeated"), ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentCharacterProgression.AstreaLevelsDefeated);
		}
	}

